code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    active_rows = [r for r in range(h) if r not in sep_rows]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in active_rows}) == 1 and grid[active_rows[0]][c] != bg]
    def spans(length, separators):
        result=[]; start=0
        for x in separators:
            if start < x: result.append((start,x))
            start=x+1
        if start<length: result.append((start,length))
        return result
    row_spans=spans(h,sep_rows); col_spans=spans(w,sep_cols)
    source=None
    for rs in row_spans:
        for cs in col_spans:
            if any(grid[r][c] != bg for r in range(*rs) for c in range(*cs)):
                source=(rs,cs); break
        if source: break
    if source is None: return [row[:] for row in grid]
    rs,cs=source
    pattern=[grid[r][cs[0]:cs[1]] for r in range(*rs)]
    out=[row[:] for row in grid]
    for rspan in row_spans:
        for cspan in col_spans:
            if rspan[1]-rspan[0] == len(pattern) and cspan[1]-cspan[0] == len(pattern[0]):
                for i,r in enumerate(range(*rspan)):
                    out[r][cspan[0]:cspan[1]]=pattern[i][:]
    return out
'''
